    /**
     * Exact match lookup in offline dictionary.
     */
    fun findExact(word: String): DictionaryEntry? {
        val trimmed = word.trim().lowercase()
        return BUILT_IN_DICTIONARY.firstOrNull { it.word.lowercase() == trimmed }
    }
